    @ParameterizedTest @ValueSource(strings={"Linux","Darwin","Windows 11"})
    void processJavaSelectionUsesThePlatformExecutable(String platform){
        assertThat(SyncScheduleProcessProbe.javaExecutable(java.nio.file.Path.of("owned-jdk"),platform))
            .isEqualTo(java.nio.file.Path.of("owned-jdk","bin",platform.equals("Windows 11")?"java.exe":"java"));
    }
    @Test void completionQuotaFailurePausesTheCurrentGrantBeforeAnotherOccurrence() throws Exception {
        var seed=createUrlSource("/fast");checkToCandidate(seed);var original=assets.get(users.findById(Long.parseLong(f.owner().id())).orElseThrow(),f.workspace(),f.project());var file=original.files().stream().filter(value->value.path().equals("project.yaml")).findFirst().orElseThrow();String content=file.content().replace("name: T9","name: "+"q".repeat(3*1024*1024));
        for(int index=0;index<2;index++){var delta=json.createObjectNode().put("format","contract-files-v1").put("contractProjectId",original.contractProjectId()).put("expectedVersion",currentVersion());delta.putArray("changes").addObject().put("path","project.yaml").put("content",content+"\n# completion candidate "+index);delta.putArray("deletes");mvc.perform(put(f.projectUrl()+"/assets").header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(delta.toString())).andExpect(status().isOk());assertThat(awaitCheck(submit(seed,checkBody().put("expectedAssetVersion",currentVersion())).path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");}
        String barrier=java.util.UUID.randomUUID().toString();var raw=sourceBody("url").put("url",node.info.path("origin").asText()+"/blocked/"+barrier);var source=body(sourceRequest("POST","/sources",f.owner(),write(raw).put("expectedAssetVersion",currentVersion())).andExpect(status().isCreated()));authorize(source,"0",f.owner());source=readSourceAsAdmin(source.path("id").asText());var old=deployment.getDefaults();String version=currentVersion();long p=Long.parseLong(f.project());int starts=sourceHostCalls(),candidates=jdbc.queryForObject("SELECT COUNT(*) FROM sync_candidates WHERE project_id=?",Integer.class,p);
        try{at("2026-11-05T01:00:00Z");driver.tick();awaitNode("received-"+barrier);long running=storage.usage(Long.parseLong(f.workspace()),p).occupiedBytes();assertThat(running).isGreaterThan(8388608);deployment.setDefaults(json.convertValue(Map.of("maxProjectStorageBytes",8388608L),com.autumnharvestc.server.collaboration.policy.DeploymentPolicyProperties.Defaults.class));release(barrier);
            String id=jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=?",String.class,p);var first=awaitCheckAs(id,f.owner());assertThat(first.path("state").asText()).isEqualTo("failed");assertThat(first.path("reasonCode").asText()).isEqualTo("storage-limit");assertThat(first.path("candidateId").isNull()).isTrue();var afterFirst=body(sourceRequest("GET",scheduleRoute(source),f.owner(),null).andExpect(status().isOk()));long settled=storage.usage(Long.parseLong(f.workspace()),p).occupiedBytes();assertThat(settled).isLessThan(running);
            at("2026-11-05T02:00:00Z");driver.tick();int checks=checkCountForTrigger(source);if(checks>1){String second=jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=? AND planned_at_utc='2026-11-05T02:00:00Z'",String.class,p);awaitCheckAs(second,f.owner());}
            System.out.println("T11_FIX1_COMPLETION "+json.createObjectNode().put("runningBytes",running).put("settledBytes",settled).put("grantEnabledAfterFailure",afterFirst.path("enabled").asBoolean()).put("scheduledChecks",checks).put("sourceStarts",sourceHostCalls()-starts).put("assetVersion",currentVersion()).put("applications",automaticApplicationCount()));
            assertThat(afterFirst.path("enabled").asBoolean()).isFalse();assertThat(afterFirst.path("pausedReasonCode").asText()).isEqualTo("storage-limit");assertThat(checks).isEqualTo(1);assertThat(sourceHostCalls()).isEqualTo(starts+1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sync_candidates WHERE project_id=?",Integer.class,p)).isEqualTo(candidates);assertThat(currentVersion()).isEqualTo(version);assertThat(automaticApplicationCount()).isZero();
        }finally{deployment.setDefaults(old);release(barrier);}
    }
    @ParameterizedTest @ValueSource(strings={"deny","regrant","NONE","removed","disabled","source"})
    void authorizationLossPausesTheFixedSubjectWithoutSelectingAnOwner(String variant) throws Exception {
        var source=createUrlSource("/fast");checkToCandidate(source);capabilities(null,Map.of("sync.manage","allow"));authorize(source,"0",editor());source=readSourceAsAdmin(source.path("id").asText());at("2026-11-05T01:00:00Z");driver.tick();awaitOneCompletedCheck(source);int starts=sourceHostCalls();
        try{
            switch(variant){
                case "deny"->capabilities(null,Map.of("sync.check","deny"));
                case "regrant"->{capabilities(null,Map.of("sync.check","deny"));capabilities(null,Map.of("sync.check","allow"));}
                case "NONE"->capabilities("NONE",Map.of());
                case "removed"->mvc.perform(delete(f.workspaceUrl()+"/members/"+editor().id()).param("expectedRevision","1").header("Authorization","Bearer "+f.owner().token())).andExpect(status().isNoContent());
                case "disabled"->users.setDisabled(Long.parseLong(editor().id()),true);
                case "source"->{var request=sourceUpdateBody(source).put("expectedAssetVersion","2");((com.fasterxml.jackson.databind.node.ObjectNode)request.path("source").path("schedule")).put("enabled",false);sourceRequest("PUT","/sources/"+source.path("id").asText(),f.owner(),request).andExpect(status().isOk());}
            }
            at("2026-11-05T02:00:00Z");assertThatCode(driver::tick).doesNotThrowAnyException();
            sourceRequest("GET",scheduleRoute(source),f.owner(),null).andExpect(status().isOk()).andExpect(jsonPath("$.enabled").value(false));assertThat(sourceHostCalls()).isEqualTo(starts);
        }finally{if(variant.equals("disabled"))users.setDisabled(Long.parseLong(editor().id()),false);}
    }
    @ParameterizedTest @ValueSource(strings={"rotate","remove"})
    void fixedCredentialVersionDoesNotAdoptNewOrRemovedMaterial(String variant) throws Exception {
        var actor=users.findById(Long.parseLong(f.owner().id())).orElseThrow();String value="{\"formatVersion\":1,\"kind\":\"http-headers\",\"headers\":[{\"name\":\"Authorization\",\"value\":\"Bearer synthetic-t9\"}]}";credentials.put(actor,f.workspace(),f.project(),"headers",new CredentialWrite("0",value));var raw=sourceBody("url").put("url",node.info.path("origin").asText()+"/auth").put("authRef","headers");var source=body(sourceRequest("POST","/sources",f.owner(),write(raw).put("expectedAssetVersion","2")).andExpect(status().isCreated()));checkToCandidate(source);authorize(source,"0",f.owner());source=readSourceAsAdmin(source.path("id").asText());at("2026-11-05T01:00:00Z");driver.tick();awaitOneCompletedCheck(source);int starts=sourceHostCalls();
        if(variant.equals("rotate"))credentials.put(actor,f.workspace(),f.project(),"headers",new CredentialWrite("1",value));else credentials.remove(actor,f.workspace(),f.project(),"headers","1");
        at("2026-11-05T02:00:00Z");assertThatCode(driver::tick).doesNotThrowAnyException();sourceRequest("GET",scheduleRoute(source),f.owner(),null).andExpect(status().isOk()).andExpect(jsonPath("$.enabled").value(false)).andExpect(jsonPath("$.pausedReasonCode").value("material-changed"));assertThat(sourceHostCalls()).isEqualTo(starts);
    }
    @Test void pausingCancelsOnlyTheScheduledCheckOwnedByThatGeneration() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=java.util.UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);authorize(source,"0",f.owner());source=readSourceAsAdmin(source.path("id").asText());at("2026-11-05T01:00:00Z");driver.tick();awaitNode("received-"+barrier);
        String id=jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=?",String.class,Long.parseLong(f.project()));
        try{sourceRequest("PUT",scheduleRoute(source),f.owner(),scheduleBody(source,"1",false)).andExpect(status().isOk());var check=body(sourceRequest("GET","/checks/"+id,f.owner(),null).andExpect(status().isOk()));assertThat(check.path("state").asText()).isIn("cancelled","cancelling");awaitNode("collected-"+barrier);assertThat(awaitCheckAs(id,f.owner()).path("candidateId").isNull()).isTrue();}
        finally{sourceRequest("POST","/checks/"+id+"/cancel",f.owner(),json.createObjectNode()).andExpect(status().isAccepted());release(barrier);}
    }
    @ParameterizedTest @ValueSource(strings={"project","workspace"})
    void deletingANonemptyScheduleScopeRemovesTheDurableOccurrences(String scope) throws Exception {
        var source=enabledHourlySource();at("2026-11-05T01:00:00Z");driver.tick();awaitOneCompletedCheck(source);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sync_occurrences WHERE project_id=?",Integer.class,Long.parseLong(f.project()))).isEqualTo(1);
        long bytes=0;for(String table:java.util.List.of("sync_sources","sync_checks","sync_candidates","sync_history","sync_operations","sync_policies","sync_occurrences"))bytes+=jdbc.query("SELECT * FROM "+table+" WHERE project_id=?",rows->{long total=0;while(rows.next())for(int column=1;column<=rows.getMetaData().getColumnCount();column++){String value=rows.getString(column);if(value!=null)total+=value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;}return total;},Long.parseLong(f.project()));assertThat(jdbc.queryForObject("SELECT body_bytes FROM collaboration_storage_objects WHERE workspace_id=? AND project_id=? AND kind='SYNC_STATE'",Long.class,Long.parseLong(f.workspace()),Long.parseLong(f.project()))).isEqualTo(bytes);
        mvc.perform(delete(scope.equals("project")?f.projectUrl():f.workspaceUrl()).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isNoContent());
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM sync_occurrences WHERE project_id=?",Integer.class,Long.parseLong(f.project()))).isZero();
    }
    @Test void persistentSchedulerDisablePreventsANewBackgroundOccurrence() throws Exception {
        var source=enabledHourlySource();at("2026-11-05T01:00:00Z");driver.tick();awaitOneCompletedCheck(source);
        try{control.change(new com.autumnharvestc.server.execution.scheduling.ScheduleControlService.Update("disabled",control.read().version()));at("2026-11-05T02:00:00Z");driver.tick();assertThat(checkCountForTrigger(source)).isEqualTo(1);}
        finally{control.change(new com.autumnharvestc.server.execution.scheduling.ScheduleControlService.Update("embedded",control.read().version()));}
    }
    @Test void anOldSchedulerGenerationCannotFulfillANewOccurrence() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=java.util.UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);authorize(source,"0",f.owner());source=readSourceAsAdmin(source.path("id").asText());at("2026-11-05T01:00:00Z");driver.tick();awaitNode("received-"+barrier);String old=jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=?",String.class,Long.parseLong(f.project()));
        try{control.change(new com.autumnharvestc.server.execution.scheduling.ScheduleControlService.Update("disabled",control.read().version()));control.change(new com.autumnharvestc.server.execution.scheduling.ScheduleControlService.Update("embedded",control.read().version()));at("2026-11-05T02:00:00Z");driver.tick();assertThat(jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=? AND planned_at_utc='2026-11-05T02:00:00Z'",String.class,Long.parseLong(f.project()))).isNotEqualTo(old);}
        finally{for(var id:jdbc.queryForList("SELECT id FROM sync_checks WHERE project_id=? AND state IN ('queued','running','waiting','cancelling')",String.class,Long.parseLong(f.project())))sourceRequest("POST","/checks/"+id+"/cancel",f.owner(),json.createObjectNode()).andExpect(status().isAccepted());release(barrier);awaitNode("collected-"+barrier);}
    }
    @Test void aLinkedManualCheckKeepsItsOwnCancellationAuthorityWhenThePlanPauses() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=java.util.UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);authorize(source,"0",f.owner());source=readSourceAsAdmin(source.path("id").asText());var manual=submit(source,checkBody().put("expectedSourceRevision","2"));awaitNode("received-"+barrier);
        try{at("2026-11-05T01:00:00Z");driver.tick();assertThat(jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=?",String.class,Long.parseLong(f.project()))).isEqualTo(manual.path("checkId").asText());
            sourceRequest("PUT",scheduleRoute(source),f.owner(),scheduleBody(source,"1",false)).andExpect(status().isOk());
            var before=jdbc.queryForObject("SELECT lease_until_utc FROM sync_checks WHERE project_id=? AND id=?",java.time.OffsetDateTime.class,Long.parseLong(f.project()),manual.path("checkId").asText());
            boolean renewed=false;long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(3);
            while(System.nanoTime()<until){var current=jdbc.queryForObject("SELECT lease_until_utc FROM sync_checks WHERE project_id=? AND id=?",java.time.OffsetDateTime.class,Long.parseLong(f.project()),manual.path("checkId").asText());if(current!=null&&before!=null&&current.isAfter(before)){renewed=true;break;}if(java.nio.file.Files.exists(node.directory.resolve("collected-"+barrier)))break;Thread.sleep(10);}
            System.out.println("SYNC_MANUAL_PLAN_PAUSE check="+manual.path("checkId").asText()+" renewedAfterPause="+renewed+" collectedBeforeRelease="+java.nio.file.Files.exists(node.directory.resolve("collected-"+barrier)));
            assertThat(renewed).as("A manual source read remains healthy across an ownership pulse after only its linked plan pauses").isTrue();
            sourceRequest("GET","/checks/"+manual.path("checkId").asText(),f.owner(),null).andExpect(status().isOk()).andExpect(jsonPath("$.state").value("running"));assertThat(java.nio.file.Files.exists(node.directory.resolve("collected-"+barrier))).isFalse();
        }finally{release(barrier);awaitCheckAs(manual.path("checkId").asText(),f.owner());}
    }
    @Test void oldGenerationCompletionCannotPauseAnExplicitlyReauthorizedGrant() throws Exception {
        checkToCandidate(createUrlSource("/fast"));String barrier=java.util.UUID.randomUUID().toString();var source=createUrlSource("/blocked/"+barrier);capabilities(null,Map.of("sync.manage","allow"));authorize(source,"0",editor());source=readSourceAsAdmin(source.path("id").asText());at("2026-11-05T01:00:00Z");driver.tick();awaitNode("received-"+barrier);String old=jdbc.queryForObject("SELECT check_id FROM sync_occurrences WHERE project_id=?",String.class,Long.parseLong(f.project()));
        try{capabilities(null,Map.of("sync.check","deny"));capabilities(null,Map.of("sync.check","allow"));authorize(source,"1",f.owner());release(barrier);var done=awaitCheckAs(old,f.owner());assertThat(done.path("candidateId").isNull()).isTrue();sourceRequest("GET",scheduleRoute(source),f.owner(),null).andExpect(status().isOk()).andExpect(jsonPath("$.generation").value("2")).andExpect(jsonPath("$.enabled").value(true)).andExpect(jsonPath("$.subjectUserId").value(f.owner().id()));}
        finally{release(barrier);}
    }
    @Test void realBackendProcessesRestartWithoutADesktopAndRetainTheUtcOccurrence() throws Exception {new SyncScheduleProcessProbe(json,node.info,key,node.process.pid()).run();}
    @Test void loweredQuotaPausesBeforeStartingASourceAndDoesNotPoisonTheNextHealthyProject() throws Exception {
        var source=createUrlSource("/fast");checkToCandidate(source);var original=assets.get(users.findById(Long.parseLong(f.owner().id())).orElseThrow(),f.workspace(),f.project());var file=original.files().stream().filter(value->value.path().equals("project.yaml")).findFirst().orElseThrow();String content=file.content().replace("name: T9","name: "+"q".repeat(3*1024*1024));
        for(int index=0;index<3;index++){var delta=json.createObjectNode().put("format","contract-files-v1").put("contractProjectId",original.contractProjectId()).put("expectedVersion",currentVersion());delta.putArray("changes").addObject().put("path","project.yaml").put("content",content+"\n# candidate "+index);delta.putArray("deletes");mvc.perform(put(f.projectUrl()+"/assets").header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(delta.toString())).andExpect(status().isOk());assertThat(awaitCheck(submit(source,checkBody().put("expectedAssetVersion",currentVersion())).path("checkId").asText()).path("state").asText()).isEqualTo("succeeded");}
        authorize(source,"0",f.owner());assertThat(storage.usage(Long.parseLong(f.workspace()),Long.parseLong(f.project())).occupiedBytes()).isGreaterThan(8388608);
        String other=anotherProject(),url=f.workspaceUrl()+"/projects/"+other;var delta=json.createObjectNode().put("format","contract-files-v1").put("contractProjectId",original.contractProjectId()).put("expectedVersion","0");delta.set("changes",node.info.path("files"));delta.putArray("deletes");mvc.perform(put(url+"/assets").header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(delta.toString())).andExpect(status().isOk());var healthy=body(mvc.perform(post(url+"/sync/sources").header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(write(sourceBody("url").put("url",node.info.path("origin").asText()+"/healthy-quota")).put("expectedAssetVersion","1").toString())).andExpect(status().isCreated()));mvc.perform(put(url+"/sync"+scheduleRoute(healthy)).header("Authorization","Bearer "+f.owner().token()).contentType("application/json").content(scheduleBody(healthy,"0",true).toString())).andExpect(status().isOk());
        var old=deployment.getDefaults();int starts=sourceHostCalls();var usageBefore=storage.usage(Long.parseLong(f.workspace()),Long.parseLong(f.project()));var grantBefore=schedules.grant(Long.parseLong(f.workspace()),Long.parseLong(f.project()),source.path("id").asText()).deepCopy();try{deployment.setDefaults(json.convertValue(Map.of("maxProjectStorageBytes",8388608L),com.autumnharvestc.server.collaboration.policy.DeploymentPolicyProperties.Defaults.class));at("2026-11-05T01:00:00Z");driver.tick();sourceRequest("GET",scheduleRoute(source),f.owner(),null).andExpect(status().isOk()).andExpect(jsonPath("$.enabled").value(false)).andExpect(jsonPath("$.pausedReasonCode").value("storage-limit"));
            var usageAfter=storage.usage(Long.parseLong(f.workspace()),Long.parseLong(f.project()));assertThat(usageAfter.occupiedBytes()).isLessThan(usageBefore.occupiedBytes());assertThat(usageAfter.reservedAuditBytes()).isLessThan(usageBefore.reservedAuditBytes());var grantAfter=schedules.grant(Long.parseLong(f.workspace()),Long.parseLong(f.project()),source.path("id").asText());for(String field:java.util.List.of("generation","sourceRevision","subjectUserId","syncCheckEpoch","materials","evaluatedThroughUtc"))assertThat(grantAfter.path(field)).isEqualTo(grantBefore.path(field));System.out.println("T11_GRANT_QUOTA "+json.createObjectNode().put("occupiedBefore",usageBefore.occupiedBytes()).put("occupiedAfter",usageAfter.occupiedBytes()).put("actualDelta",usageAfter.actualBytes()-usageBefore.actualBytes()).put("reservedDelta",usageAfter.reservedAuditBytes()-usageBefore.reservedAuditBytes()));
            String healthyCheck=jdbc.queryForObject("SELECT id FROM sync_checks WHERE project_id=?",String.class,Long.parseLong(other));long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(10);String state="";while(System.nanoTime()<until){state=jdbc.queryForObject("SELECT state FROM sync_checks WHERE project_id=? AND id=?",String.class,Long.parseLong(other),healthyCheck);if(state.equals("succeeded"))break;Thread.sleep(20);}assertThat(state).isEqualTo("succeeded");assertThat(sourceHostCalls()).isEqualTo(starts+1);assertThat(checkCountForTrigger(source)).isZero();
        }finally{deployment.setDefaults(old);mvc.perform(delete(url).header("Authorization","Bearer "+f.owner().token())).andExpect(status().isNoContent());}
    }
